-- Read-only post-deployment privilege verification. No RPC invocation or user data.
BEGIN TRANSACTION READ ONLY;
WITH helpers(signature) AS (VALUES
 ('public.workspace_notify(uuid,text,text,text,uuid,text,text)'),
 ('public.eco_activity(text,uuid,text)'), ('public.eco_space_owner(text,uuid)')),
api_roles(role_name) AS (VALUES ('anon'),('authenticated')),
expected_tables(name) AS (VALUES ('application_history'),('applications'),('campus_announcements'),('communities'),('community_comments'),('community_members'),('community_posts'),('community_reactions'),('community_resources'),('ecosystem_activity'),('event_registrations'),('events'),('founder_profiles'),('mentor_connections'),('mentor_profiles'),('mentor_sessions'),('notifications'),('opportunities'),('organizations'),('posts'),('profiles'),('project_activity'),('project_code_redemptions'),('project_files'),('project_invite_codes'),('project_members'),('project_tasks'),('projects'),('saved_opportunities'),('space_join_requests'),('student_details'),('student_preferences'),('support_reports'),('university_connection_requests'),('university_domains'),('university_student_invitations'),('university_student_memberships'),('workspace_invitations')),
expected_rpcs(name) AS (VALUES ('accept_university_invitation'),('assign_community_member_by_email'),('assign_project_member_by_email'),('can_manage_university'),('cancel_university_invitation'),('create_community'),('create_project'),('eco_announcement'),('eco_applicant_summary'),('eco_applicants'),('eco_campus_invitation_decide'),('eco_campus_invitations'),('eco_campus_invite'),('eco_campus_progress'),('eco_campus_requests'),('eco_code_accept'),('eco_code_create'),('eco_code_preview'),('eco_code_revoke'),('eco_connections'),('eco_context'),('eco_domain_save'),('eco_eligible'),('eco_event_attending'),('eco_event_save'),('eco_invitation_cancel'),('eco_invitation_decide'),('eco_invite'),('eco_join_request'),('eco_manager'),('eco_member_remove'),('eco_mentor_decide'),('eco_mentor_profile'),('eco_mentor_request'),('eco_mentor_session'),('eco_opportunity_save'),('eco_portfolio'),('eco_portfolio_projects'),('eco_relationship_directory'),('eco_request_decide'),('eco_scope_allowed'),('eco_space_save'),('eco_space_visible'),('eco_task_save'),('eco_university_connect'),('eco_university_decide'),('enroll_university_student'),('finish_onboarding'),('is_community_captain'),('is_platform_admin'),('is_project_head'),('list_space_member_names'),('list_university_students'),('revoke_university_student'),('update_student_workspace_profile'),('workspace_application_status'),('workspace_applied'),('workspace_apply'),('workspace_audience'),('workspace_create'),('workspace_directory'),('workspace_invite'),('workspace_join'),('workspace_member'),('workspace_post'),('workspace_publish'),('workspace_react'),('workspace_ready'),('workspace_refresh_reminders'),('workspace_register'),('workspace_resource'),('workspace_save'),('workspace_stats'),('workspace_task'))
SELECT jsonb_pretty(jsonb_build_object(
 'helpers', (SELECT jsonb_agg(jsonb_build_object('function',signature,'exists',to_regprocedure(signature) IS NOT NULL,'anon_execute',has_function_privilege('anon',to_regprocedure(signature),'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',to_regprocedure(signature),'EXECUTE'),'service_execute',has_function_privilege('service_role',to_regprocedure(signature),'EXECUTE'))) FROM helpers),
 'public_rpcs', (SELECT jsonb_agg(jsonb_build_object('name',e.name,'exists',p.oid IS NOT NULL,'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef)) FROM expected_rpcs e LEFT JOIN pg_namespace n ON n.nspname='public' LEFT JOIN pg_proc p ON p.pronamespace=n.oid AND p.proname=e.name),
 'truncate', (SELECT jsonb_agg(jsonb_build_object('table',name,'exists',to_regclass('public.'||name) IS NOT NULL,'anon',has_table_privilege('anon',to_regclass('public.'||name),'TRUNCATE'),'authenticated',has_table_privilege('authenticated',to_regclass('public.'||name),'TRUNCATE'))) FROM expected_tables),
 'notification_update', (SELECT jsonb_agg(jsonb_build_object('role',role_name,'table_update',has_table_privilege(role_name,'public.notifications','UPDATE'),'writable_columns',(SELECT coalesce(jsonb_agg(column_name ORDER BY column_name),'[]') FROM information_schema.columns WHERE table_schema='public' AND table_name='notifications' AND has_column_privilege(role_name,'public.notifications',column_name,'UPDATE')))) FROM api_roles),
 'nested_caller_owners', (SELECT jsonb_agg(jsonb_build_object('caller',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'helper',h.signature,'owner_can_execute',has_function_privilege(p.proowner,to_regprocedure(h.signature),'EXECUTE'))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN helpers h WHERE n.nspname='public' AND p.prokind='f' AND p.prosrc LIKE '%'||split_part(h.signature,'(',1)||'(%')
)) AS privilege_verification;
ROLLBACK;
-- Expected: helpers exist, anon/authenticated false, owner/service access retained;
-- all listed RPCs exist with authenticated true; all tables exist with truncate false;
-- notification table_update false for both, columns [] for anon and [read_at] for authenticated;
-- all nested callers SECURITY DEFINER and owner_can_execute true.
